/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Sheet, collectDeps } from './eval.js'
import { formatValue } from './format.js'
import { compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
    }
    throw e
  }

  const addresses = Array.from(cells.keys()).sort(compareAddresses)

  const out = []
  const sheet = new Sheet(cells)

  if (mode === 'values') {
    for (const addr of addresses) {
      const value = sheet.getValue(addr)
      out.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const addr of addresses) {
      const ast = sheet.getAst(addr)
      const line = [`${addr}:`]
      if (ast) {
        const deps = collectDeps(ast)
        for (const d of deps) line.push(` ${d}`)
      }
      out.push(line.join(''))
    }
  }

  process.stdout.write(out.map((l) => l + '\n').join(''))
  process.exit(0)
}

main()
"}

