export function parseReference(s) {
  let rest = s
  let scheme = null
  let schemeEndIdx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') { schemeEndIdx = i; break }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (schemeEndIdx !== -1) {
    scheme = rest.slice(0, schemeEndIdx)
    rest = rest.slice(schemeEndIdx + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    const rem = rest.slice(2)
    let end = rem.length
    for (let i = 0; i < rem.length; i++) {
      const c = rem[i]
      if (c === '/' || c === '?' || c === '#') { end = i; break }
    }
    authority = rem.slice(0, end)
    rest = rem.slice(end)
  }

  let query = null
  let fragment = null
  let path
  const qIdx = rest.indexOf('?')
  const hIdx = rest.indexOf('#')
  if (hIdx === -1) {
    if (qIdx === -1) {
      path = rest
    } else {
      path = rest.slice(0, qIdx)
      query = rest.slice(qIdx + 1)
    }
  } else if (qIdx !== -1 && qIdx < hIdx) {
    path = rest.slice(0, qIdx)
    query = rest.slice(qIdx + 1, hIdx)
    fragment = rest.slice(hIdx + 1)
  } else {
    path = rest.slice(0, hIdx)
    fragment = rest.slice(hIdx + 1)
  }

  return { scheme, authority, path, query, fragment }
