  let host = null
  let port = null
  let hasPort = false
  if (authorityInfo) {
    userinfo = authorityInfo.userinfo !== null ? normalizeComponent('userinfo', authorityInfo.userinfo, lineNo) : null
    host = normalizeComponent('host', authorityInfo.host, lineNo)
    port = authorityInfo.port
    hasPort = authorityInfo.hasPort
  }

  const query = parsed.query !== null ? normalizeComponent('query', parsed.query, lineNo) : null
  const fragment = parsed.fragment !== null ? normalizeComponent('fragment', parsed.fragment, lineNo) : null

  if (host !== null) host = asciiLower(host)

  if (hasPort) {
    if (port === '' || (scheme !== null && DEFAULT_PORTS[scheme] === port)) {
      hasPort = false
      port = null
    }
