  if (parsed.authority !== null && finalPath === '') finalPath = '/'

  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (parsed.authority !== null) {
    out += '//'
    if (userinfo !== null) out += userinfo + '@'
    out += host
    if (hasPort) out += ':' + port
  }
