{"file_path":"./src/merge3.js","content":"import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/** Group the changes from both sides into regions, per the merge spec. */
function groupRegions(mineChanges, theirsChanges) {
  const tagged = []
  for (const c of mineChanges) tagged.push({ ...c, side: 'mine' })
  for (const c of theirsChanges) tagged.push({ ...c, side: 'theirs' })
  tagged.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let idx = 0
  while (idx < tagged.length) {
    let start = tagged[idx].baseStart
    let end = tagged[idx].baseEnd
    const group = [tagged[idx]]
    idx++
    while (idx < tagged.length && tagged[idx].baseStart <= end) {
      if (tagged[idx].baseEnd > end) end = tagged[idx].baseEnd
      group.push(tagged[idx])
      idx++
    }
    regions.push({ baseStart: start, baseEnd: end, changes: group })
  }
  return regions
}

/** The shift applied to matched base lines just before `pos`, for one side's changes. */
function shiftAt(changes, pos) {
  let shift = 0
  for (const c of changes) {
    if (c.baseEnd <= pos) shift = c.sideEnd - c.baseEnd
    else break
  }
  return shift
}

/** The lines a side contributes to a region, per the multi-change replacement rule. */
function sideLinesForRegion(region, side, sideDoc, sideChangesAll) {
  const touching = region.changes.filter(c => c.side === side)
  if (touching.length === 0) {
    const shift = shiftAt(sideChangesAll, region.baseStart)
    return sideDoc.slice(region.baseStart + shift, region.baseEnd + shift)
  }
  let minBaseStart = touching[0].baseStart
  let maxBaseEnd = touching[0].baseEnd
  let startChange = touching[0]
  let endChange = touching[0]
  for (const c of touching) {
    if (c.baseStart < minBaseStart) {
      minBaseStart = c.baseStart
      startChange = c
    }
    if (c.baseEnd > maxBaseEnd) {
      maxBaseEnd = c.baseEnd
      endChange = c
    }
  }
  const sideStart = startChange.sideStart - (minBaseStart - region.baseStart)
  const sideEnd = endChange.sideEnd + (region.baseEnd - maxBaseEnd)
  return sideDoc.slice(sideStart, sideEnd)
}

/**
 * Compute the ordered list of blocks describing the merge of `mine` and
 * `theirs` against `base`. Each block is one of:
 *   { type: 'stable', lines }
 *   { type: 'mine' | 'theirs' | 'both', lines }
 *   { type: 'conflict', mine, base, theirs }
 */
export function computeBlocks(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = groupRegions(mineChanges, theirsChanges)

  const blocks = []
  let last = 0
  for (const region of regions) {
    if (region.baseStart > last) {
      blocks.push({ type: 'stable', lines: base.slice(last, region.baseStart) })
    }
    const mineLines = sideLinesForRegion(region, 'mine', mine, mineChanges)
    const theirsLines = sideLinesForRegion(region, 'theirs', theirs, theirsChanges)
    const baseLines = base.slice(region.baseStart, region.baseEnd)

    if (arraysEqual(mineLines, theirsLines)) {
      blocks.push({ type: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      blocks.push({ type: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      blocks.push({ type: 'mine', lines: mineLines })
    } else {
      blocks.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }
    last = region.baseEnd
  }
  if (base.length > last) {
    blocks.push({ type: 'stable', lines: base.slice(last, base.length) })
  }
  return blocks
}
"}

