{"file_path":"./src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { computeBlocks } from './merge3.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitLines(raw) {
  const lines = raw.split('\n')
  if (raw.endsWith('\n')) lines.pop()
  return lines
}

function splitDocuments(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts
}

function renderMerge(blocks, includeBase) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.type === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      for (const line of block.mine) out.push(line)
      if (includeBase) {
        out.push('||||||| base')
        for (const line of block.base) out.push(line)
      }
      out.push('=======')
      for (const line of block.theirs) out.push(line)
      out.push('>>>>>>> theirs')
    } else {
      for (const line of block.lines) out.push(line)
    }
  }
  return { out, conflict }
}

function renderRegions(blocks) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.type === 'conflict') {
      conflict = true
      out.push(`conflict mine=${block.mine.length} base=${block.base.length} theirs=${block.theirs.length}`)
    } else {
      out.push(`${block.type} ${block.lines.length}`)
    }
  }
  return { out, conflict }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const raw = readFileSync(0, 'utf8')
  const lines = splitLines(raw)
  const parts = splitDocuments(lines)
  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const blocks = computeBlocks(mine, base, theirs)

  let result
  if (mode === 'merge') result = renderMerge(blocks, true)
  else if (mode === 'merge2') result = renderMerge(blocks, false)
  else result = renderRegions(blocks)

  const text = result.out.length === 0 ? '' : result.out.join('\n') + '\n'
  process.stdout.write(text)
  process.exit(result.conflict ? 1 : 0)
}

main()
"}

