{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-9kPrtA/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { threeWayMerge } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }
  return docs
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('error: usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const docs = splitDocuments(input)
  if (docs.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }
  const [mine, base, theirs] = docs

  const regions = threeWayMerge(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}\n`)
      } else {
        out.push(`${region.kind} ${region.lines.length}\n`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine\n')
        for (const line of region.mineLines) out.push(`${line}\n`)
        if (mode === 'merge') {
          out.push('||||||| base\n')
          for (const line of region.baseLines) out.push(`${line}\n`)
        }
        out.push('=======\n')
        for (const line of region.theirsLines) out.push(`${line}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const line of region.lines) out.push(`${line}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(conflict ? 1 : 0)
}

main()
"}

