import { BucketPolicy, WindowPolicy, isValidToken } from './policies.js'

const UINT_PATTERN = /^(0|[1-9][0-9]*)$/

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function parseUint(text, field, min) {
  if (!UINT_PATTERN.test(text)) {
    throw { field, min }
  }
  const value = BigInt(text)
  if (value < min) {
    throw { field, min }
  }
  return value
}

function fail(line, reason) {
  throw new LimiterError(line, reason)
}

function requireUint(line, text, field, min) {
  try {
    return parseUint(text, field, min)
  } catch {
    fail(line, `${field} must be an integer of at least ${min}`)
  }
}

/**
 * Parses and simulates the limiter file described by `input`, producing the
 * per-event verdicts. Throws a LimiterError on the first line that fails to
 * parse or validate.
 */
export function simulate(input) {
  const lines = splitLines(input)

  const policies = new Map()
  const routePrefixes = new Set()
  const routes = []
  let firstEventSeen = false
  let lastTick = null

  const events = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (firstEventSeen) fail(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capS, refillS, perS] = tokens
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = requireUint(lineNo, capS, 'capacity', 1n)
      const refill = requireUint(lineNo, refillS, 'refill', 0n)
      const per = requireUint(lineNo, perS, 'per', 1n)
      policies.set(name, new BucketPolicy(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitS, spanS] = tokens
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = requireUint(lineNo, limitS, 'limit', 0n)
      const span = requireUint(lineNo, spanS, 'span', 1n)
      policies.set(name, new WindowPolicy(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!isValidToken(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(lineNo, `unknown policy ${name}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const [, tickS, key] = tokens
      const tick = requireUint(lineNo, tickS, 'tick', 0n)
      if (!isValidToken(key)) fail(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      firstEventSeen = true
      events.push({ tick, key })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  // Resolve, for each key that appears, the longest matching route.
  const routeCache = new Map()
  function routeFor(key) {
    if (routeCache.has(key)) return routeCache.get(key)
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        if (best === null || route.prefix.length > best.prefix.length) best = route
      }
    }
    routeCache.set(key, best)
    return best
  }

  const results = []
  for (const { tick, key } of events) {
    const route = routeFor(key)
    if (route === null) {
      results.push({ tick, key, allow: true, policy: null })
      continue
    }
    const routePolicies = route.policyNames.map((name) => policies.get(name))
    for (const p of routePolicies) p.advance(key, tick)
    let deniedBy = null
    for (let i = 0; i < routePolicies.length; i++) {
      if (!routePolicies[i].allows(key, tick)) {
        deniedBy = route.policyNames[i]
        break
      }
    }
    if (deniedBy === null) {
      for (const p of routePolicies) p.record(key, tick)
      results.push({ tick, key, allow: true, policy: null })
    } else {
      results.push({ tick, key, allow: false, policy: deniedBy })
    }
  }

  return results
}
