 * Policy implementations: token buckets and sliding windows.
 *
 * Each policy keeps one independent state per key, created lazily the
 * first time a key reaches it. All counting is done with BigInt so that
 * arbitrarily large capacities/limits/ticks never lose precision, and so
 * that the token-bucket refill fraction is kept exact rather than rounded.
 */

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.byKey = new Map()
  }

  advance(key, tick) {
    let s = this.byKey.get(key)
    if (!s) {
      // Starts full when the key first reaches it.
      s = { tokensNum: this.capacity * this.per, lastTick: tick }
      this.byKey.set(key, s)
      return
    }
    const n = tick - s.lastTick
    if (n > 0n) {
      s.tokensNum += this.refill * n
      const cap = this.capacity * this.per
      if (s.tokensNum > cap) s.tokensNum = cap
      s.lastTick = tick
    }
  }

  allow(key) {
    const s = this.byKey.get(key)
    return s.tokensNum >= this.per
  }

  record(key) {
    const s = this.byKey.get(key)
    s.tokensNum -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.byKey = new Map()
  }

  advance(key, tick) {
    let s = this.byKey.get(key)
    if (!s) {
      s = { ticks: [] }
      this.byKey.set(key, s)
    }
    const threshold = tick - this.span
    let i = 0
    while (i < s.ticks.length && s.ticks[i] <= threshold) i++
    if (i > 0) s.ticks.splice(0, i)
  }

  allow(key) {
    const s = this.byKey.get(key)
    return BigInt(s.ticks.length) < this.limit
  }

  record(key, tick) {
    const s = this.byKey.get(key)
    s.ticks.push(tick)
  }
}
"}

