 * Parses a limiter file into policies, routes and an event log.
 *
 * Throws a ParseError carrying the 1-based source line number and the
 * message text (without the "error: line N: " prefix) on any failure.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
    this.reason = message
  }
}

function fail(line, message) {
  throw new ParseError(line, message)
}

function checkName(line, word, what) {
  if (!NAME_RE.test(word)) fail(line, `invalid ${what} ${word}`)
}

function parseInt_(line, word, field, least) {
  if (!INT_RE.test(word)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < BigInt(least)) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map() // name -> { name, kind, instance }
  const routes = [] // { prefix, policies: [instance...] }
  const routePrefixes = new Set()
  const events = []

  let seenEvent = false
  let lastTick = null

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = tokens
      checkName(lineNo, name, 'policy name')
      const capacity = parseInt_(lineNo, capacityStr, 'capacity', 1)
      const refill = parseInt_(lineNo, refillStr, 'refill', 0)
      const per = parseInt_(lineNo, perStr, 'per', 1)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, { name, instance: new TokenBucket(name, capacity, refill, per) })
      continue
    }

    if (directive === 'window') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
      checkName(lineNo, name, 'policy name')
      const limit = parseInt_(lineNo, limitStr, 'limit', 0)
      const span = parseInt_(lineNo, spanStr, 'span', 1)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, { name, instance: new SlidingWindow(name, limit, span) })
      continue
    }

    if (directive === 'route') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      checkName(lineNo, prefix, 'route prefix')
      if (routePrefixes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      const instances = []
      for (const pname of policyNames) {
        const p = policies.get(pname)
        if (!p) fail(lineNo, `unknown policy ${pname}`)
        instances.push(p.instance)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policies: instances })
      continue
    }

    if (directive === 'event') {
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const [, tickStr, key] = tokens
      const tick = parseInt_(lineNo, tickStr, 'tick', 0)
      checkName(lineNo, key, 'key')
      if (lastTick !== null && tick < lastTick) fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      seenEvent = true
      events.push({ line: lineNo, tick, key })
      continue
    }

    fail(lineNo, `unknown directive ${directive}`)
  }

  return { routes, events }
}
