  let parsed
  try {
    parsed = parse(text)
  } catch (e) {
    if (e instanceof ParseError) {
      process.stderr.write(`error: line ${e.line}: ${e.reason}\n`)
      process.exit(2)
      return
    }
    throw e
  }

  const { routes, events } = parsed

  const out = []
  const totals = new Map() // key -> { allowed, denied }

  for (const ev of events) {
