/**
 * Detects a cycle by running a depth-first search from each task in
 * ascending name order, walking each task's dependencies in ascending
 * name order. Throws a CliError describing the first cycle found, or
 * does nothing when the graph is acyclic.
 */
export function checkAcyclic(tasks, adjacency) {
  const names = [...tasks.keys()].sort()
  const color = new Map(names.map((n) => [n, 0])) // 0 white, 1 gray, 2 black
  const stack = []

  function visit(node) {
    color.set(node, 1)
    stack.push(node)
    const deps = [...(adjacency.get(node) || [])].sort()
    for (const dep of deps) {
      const c = color.get(dep)
      if (c === 1) {
        const idx = stack.indexOf(dep)
        throw cycleError([...stack.slice(idx), dep])
      }
      if (c === 0) {
        visit(dep)
      }
    }
    color.set(node, 2)
    stack.pop()
  }

  for (const name of names) {
    if (color.get(name) === 0) {
      visit(name)
    }
  }
}

/**
 * Computes start, finish and depth for every task, assuming unlimited
 * workers and an acyclic graph. Returns a Map name -> { start, finish, depth }.
 */
export function computeTimings(tasks, adjacency) {
  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const deps = adjacency.get(name)
    let start = 0
    let depth = 0
    if (deps && deps.size > 0) {
      let maxFinish = 0
      let maxDepth = -1
      for (const dep of deps) {
        const info = compute(dep)
        if (info.finish > maxFinish) maxFinish = info.finish
        if (info.depth > maxDepth) maxDepth = info.depth
      }
      start = maxFinish
      depth = maxDepth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) {
    compute(name)
  }

  return memo
}

/**
 * Computes the scheduling priority of every task: its own cost plus the
 * greatest priority among the tasks that directly depend on it (0 when
 * nothing depends on it). Returns a Map name -> priority.
 */
export function computePriorities(tasks, adjacency) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [target, deps] of adjacency) {
    for (const dep of deps) {
      dependents.get(dep).push(target)
    }
  }

  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      const p = compute(dependent)
      if (p > best) best = p
    }
    const priority = tasks.get(name) + best
    memo.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) {
    compute(name)
  }

  return memo
}
"}

