 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 */

export class PctError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/**
 * Parse a URI reference into its generic-syntax components.
 *
 * Returns { scheme, hasAuthority, userinfo, host, port, path, query, fragment }.
 * Absent components are `null`; the empty string denotes an empty-but-present
 * component. `path` is always a string (possibly empty).
 */
export function parseUri(s) {
  let schemeEnd = -1
  for (let j = 0; j < s.length; j++) {
    const c = s[j]
    if (c === ':') {
      schemeEnd = j
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let scheme = null
  let rest = s
  if (schemeEnd !== -1) {
    scheme = s.slice(0, schemeEnd)
    rest = s.slice(schemeEnd + 1)
  }

  let hasAuthority = false
  let userinfo = null
  let host = null
  let port = null

  if (rest.startsWith('//')) {
    hasAuthority = true
    const r2 = rest.slice(2)
    let end = r2.length
    for (let j = 0; j < r2.length; j++) {
      const c = r2[j]
      if (c === '/' || c === '?' || c === '#') {
        end = j
        break
      }
    }
    const authority = r2.slice(0, end)
    rest = r2.slice(end)

    const lastAt = authority.lastIndexOf('@')
    let hostport = authority
    if (lastAt !== -1) {
      userinfo = authority.slice(0, lastAt)
      hostport = authority.slice(lastAt + 1)
    }

    const lastBracket = hostport.lastIndexOf(']')
    const colonIdx = hostport.indexOf(':', lastBracket + 1)
    if (colonIdx !== -1) {
      host = hostport.slice(0, colonIdx)
      port = hostport.slice(colonIdx + 1)
    } else {
      host = hostport
    }
  }

  const m = /^([^?#]*)(\?[^#]*)?(#.*)?$/.exec(rest)
  const path = m[1]
  const query = m[2] !== undefined ? m[2].slice(1) : null
  const fragment = m[3] !== undefined ? m[3].slice(1) : null

  return { scheme, hasAuthority, userinfo, host, port, path, query, fragment }
}

/** Serialize the components back into a URI-reference string. */
export function serializeUri(u) {
  let out = ''
  if (u.scheme !== null) out += u.scheme + ':'
  if (u.hasAuthority) {
    out += '//'
    if (u.userinfo !== null) out += u.userinfo + '@'
    out += u.host
    if (u.port !== null) out += ':' + u.port
  }
  out += u.path
  if (u.query !== null) out += '?' + u.query
  if (u.fragment !== null) out += '#' + u.fragment
  return out
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isUnreserved(ch) {
  return /[A-Za-z0-9\-._~]/.test(ch)
}

function fixPct(str, component) {
  let out = ''
  let i = 0
  while (i < str.length) {
    const c = str[i]
    if (c === '%') {
      const h1 = str[i + 1]
      const h2 = str[i + 2]
      if (!isHexDigit(h1) || !isHexDigit(h2)) {
        throw new PctError(component)
      }
      const hex = (h1 + h2).toUpperCase()
      const code = parseInt(hex, 16)
      const ch = String.fromCharCode(code)
      if (isUnreserved(ch)) {
        out += ch
      } else {
        out += '%' + hex
      }
      i += 3
    } else {
      out += c
      i += 1
    }
  }
  return out
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Remove dot segments from a path per RFC 3986 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  const output = []
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
        if (idx === -1) idx = input.length
      } else {
        idx = input.indexOf('/')
        if (idx === -1) idx = input.length
      }
      output.push(input.slice(0, idx))
      input = input.slice(idx)
    }
  }
  return output.join('')
}

/** Normalize the components of `u` in place, and return it. May throw PctError. */
export function normalizeUri(u) {
  if (u.scheme !== null) u.scheme = asciiLower(u.scheme)

  u.path = fixPct(u.path, 'path')
  if (u.userinfo !== null) u.userinfo = fixPct(u.userinfo, 'userinfo')
  if (u.hasAuthority) u.host = fixPct(u.host, 'host')
  if (u.query !== null) u.query = fixPct(u.query, 'query')
  if (u.fragment !== null) u.fragment = fixPct(u.fragment, 'fragment')

  if (u.hasAuthority) u.host = asciiLower(u.host)

  if (u.hasAuthority && u.port !== null) {
    const def = u.scheme !== null ? DEFAULT_PORTS[u.scheme] : undefined
    if (u.port === '' || (def !== undefined && u.port === def)) {
      u.port = null
    }
  }

  u.path = removeDotSegments(u.path)

  if (u.hasAuthority && u.path === '') u.path = '/'

  return u
}

function mergePaths(base, ref) {
  if (base.hasAuthority && base.path === '') {
    return '/' + ref.path
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return ref.path
  return base.path.slice(0, idx + 1) + ref.path
}

/**
 * Resolve reference `ref` against `base` per RFC 3986 5.2.2 (strict).
 * `base` must have a scheme. Returns a new, un-normalized components object.
 */
export function resolveUri(base, ref) {
  const target = {
    scheme: null,
    hasAuthority: false,
    userinfo: null,
    host: null,
    port: null,
    path: '',
    query: null,
    fragment: ref.fragment,
  }

  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.hasAuthority = ref.hasAuthority
    target.userinfo = ref.userinfo
    target.host = ref.host
    target.port = ref.port
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    target.scheme = base.scheme
    if (ref.hasAuthority) {
      target.hasAuthority = true
      target.userinfo = ref.userinfo
      target.host = ref.host
      target.port = ref.port
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      target.hasAuthority = base.hasAuthority
      target.userinfo = base.userinfo
      target.host = base.host
      target.port = base.port
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== null ? ref.query : base.query
      } else {
        if (ref.path.startsWith('/')) {
          target.path = removeDotSegments(ref.path)
        } else {
          target.path = removeDotSegments(mergePaths(base, ref))
        }
        target.query = ref.query
      }
    }
  }

  return target
}
