{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import fs from 'node:fs'
import { parseUri, serializeUri, normalizeUri, resolveUri, PctError } from './uri.js'

class UsageError extends Error {}
class CliError extends Error {}

function splitRecords(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    throw new UsageError()
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')
  const records = splitRecords(input)

  const outputs = []
  for (let idx = 0; idx < records.length; idx++) {
    const lineNo = idx + 1
    const line = records[idx]

    if (mode === 'normalize') {
      const u = parseUri(line)
      try {
        normalizeUri(u)
      } catch (e) {
        if (e instanceof PctError) {
          throw new CliError(`line ${lineNo}: ${e.message}`)
        }
        throw e
      }
      outputs.push(serializeUri(u))
    } else {
      const sp = line.indexOf(' ')
      if (sp === -1) {
        throw new CliError(`line ${lineNo}: expected a base and a reference`)
      }
      const baseStr = line.slice(0, sp)
      const refStr = line.slice(sp + 1)

      const base = parseUri(baseStr)
      if (base.scheme === null) {
