{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-FlJhVX/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parser.js'
import { countElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }
  const mode = args[0]

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      if (err.line === null || err.line === undefined) {
        fail(err.message)
      } else {
        fail(`line ${err.line}: ${err.message}`)
      }
    }
    throw err
  }

  const { rounds, winner } = countElection(election)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, idx) => {
      const entries = [...round.votes.entries()]
      entries.sort((a, b) => {
        if (b[1] !== a[1]) return b[1] - a[1]
        return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
      })
      const parts = entries.map(([name, v]) => `${name}=${v}`)
      out.push(`round ${idx + 1}: ${parts.join(' ')} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }

  out.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(out.join('\n') + '\n')
  process.exit(0)
}

main()
"}

