export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  at(type, value) {
    const t = this.peek()
    if (t.type !== type) return false
    if (value !== undefined && t.value !== value) return false
    return true
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type, value) {
    if (!this.at(type, value)) {
      throw new ParseError(`expected ${type}${value ? ' ' + value : ''}`)
    }
    return this.next()
  }

  parseFormula() {
    const node = this.parseExpr()
    this.expect('EOF')
    return node
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.at('OP') && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { kind: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.at('OP', '+') || this.at('OP', '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { kind: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.at('OP', '*') || this.at('OP', '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { kind: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.at('OP', '^')) {
      this.next()
      const right = this.parsePower()
      return { kind: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('OP', '+') || this.at('OP', '-')) {
      const op = this.next().value
      const operand = this.parseUnary()
      return { kind: 'unary', op, operand }
    }
    return this.parseAtom()
  }

  parseAtom() {
    if (this.at('NUMBER')) {
      const t = this.next()
      return { kind: 'number', value: Number(t.value) }
    }
    if (this.at('LPAREN')) {
      this.next()
      const e = this.parseExpr()
      this.expect('RPAREN')
      return e
    }
    if (this.at('NAME')) {
      const t = this.next()
      const upper = t.value.toUpperCase()
      if (this.at('LPAREN')) {
        this.next()
        const args = []
        if (!this.at('RPAREN')) {
          args.push(this.parseArgument())
          while (this.at('COMMA')) {
            this.next()
            args.push(this.parseArgument())
          }
        }
        this.expect('RPAREN')
        return { kind: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { kind: 'bool', value: true }
      if (upper === 'FALSE') return { kind: 'bool', value: false }
      return { kind: 'address', raw: t.value }
    }
    throw new ParseError('unexpected token')
  }

  parseArgument() {
    // Try to parse a bare range: NAME COLON NAME, occupying the whole
    // argument (terminated by a comma or closing paren).
    if (this.at('NAME')) {
      const save = this.pos
      const from = this.next()
      if (this.at('COLON')) {
        this.next()
        if (this.at('NAME')) {
          const to = this.next()
          if (this.at('COMMA') || this.at('RPAREN')) {
            return { kind: 'range', from: from.value, to: to.value }
          }
        }
      }
      this.pos = save
    }
    return this.parseExpr()
  }
}

export function parseFormula(src) {
  const tokens = tokenize(src)
  const parser = new Parser(tokens)
  return parser.parseFormula()
}

export { LexError }
"}

