const ERR_ERR = { type: 'error', value: '#ERR!' }
const ERR_NAME = { type: 'error', value: '#NAME?' }
const ERR_CYCLE = { type: 'error', value: '#CYCLE!' }

const CALL_ARITY = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
