/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatNumber } from './format.js'
import { compareAddr } from './address.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'error':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'text':
      return v.value
    default:
      throw new Error(`unexpected value type ${v.type}`)
  }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readStdinSync()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const sortedKeys = [...cells.entries()]
    .map(([key, cell]) => ({ key, col: cell.col, row: cell.row }))
    .sort(compareAddr)
    .map((e) => e.key)

  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const key of sortedKeys) {
      const cell = cells.get(key)
      const value = evaluator.getValue(key)
      out.push(`${cell.canonical}=${formatValue(value)}`)
    }
  } else {
    const evaluator = new Evaluator(cells)
    for (const key of sortedKeys) {
      const cell = cells.get(key)
      let depsList = []
      if (cell.content.startsWith('=')) {
        const ast = evaluator.getAst(key)
        if (ast) depsList = collectDeps(ast)
      }
      const parts = [`${cell.canonical}:`, ...depsList]
      out.push(parts.join(' '))
    }
  }

  process.stdout.write(out.length > 0 ? out.join('\n') + '\n' : '')
  process.exit(0)
}

function readStdinSync() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

main()
"}

