export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isDigit = (ch) => ch >= '0' && ch <= '9'
const isHex = (ch) => isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
const isBin = (ch) => ch === '0' || ch === '1'
const isOct = (ch) => ch >= '0' && ch <= '7'
const isAlpha = (ch) => (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_'
const isAlnum = (ch) => isAlpha(ch) || isDigit(ch)
const isWS = (ch) => ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n'

/**
 * Scans `input` and returns an array of tokens `{ kind, line, col, text }`.
 * `text` is the source text for every kind except `string` and `rawstring`,
 * for which it is the decoded value written as a JSON string. Throws a
 * `LexError` at the first problem found.
 */
export function scan(input) {
  const { chars, lines, cols } = computePositions(input)
  const n = chars.length
  const tokens = []
  let i = 0

  function consumeDigitRun(j, test) {
    let count = 0
    let lastWasDigit = false
    while (j < n) {
      const ch = chars[j]
      if (test(ch)) {
        j++
        count++
        lastWasDigit = true
      } else if (ch === '_' && lastWasDigit && j + 1 < n && test(chars[j + 1])) {
        j++
        lastWasDigit = false
      } else {
        break
      }
    }
    return { j, count }
  }

  while (i < n) {
    const ch = chars[i]

    if (isWS(ch)) {
      i++
      continue
    }

    if (ch === '/' && i + 1 < n && chars[i + 1] === '/') {
      i += 2
      while (i < n && chars[i] !== '\n') i++
