function expandCorners(from, to, out) {
  if (!from.valid || !to.valid) return
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      out.add(col + ':' + row)
    }
  }
}

export function collectDeps(node, out) {
  if (!node) return
  switch (node.type) {
    case 'Num':
    case 'Bool':
      return
    case 'Addr':
      if (node.valid) out.add(node.col + ':' + node.row)
      return
    case 'Range':
      expandCorners(node.from, node.to, out)
      return
    case 'Unary':
      collectDeps(node.operand, out)
      return
    case 'BinOp':
      collectDeps(node.left, out)
      collectDeps(node.right, out)
      return
    case 'Call':
      for (const a of node.args) collectDeps(a, out)
      return
    default:
      throw new Error('unknown node type ' + node.type)
