{"file_path":"src/merge.js","content":"import { diffAgainstBase } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let k = 0; k < a.length; k++) {
    if (a[k] !== b[k]) return false
  }
  return true
}

// Build the lines a side contributes to a region [start, end) of the base,
// given the changes from that side which touch the region.
function sideContribution(start, end, base, changes) {
  if (changes.length === 0) return base.slice(start, end)
  const result = []
  let pos = start
  for (const c of changes) {
    for (let k = pos; k < c.baseStart; k++) result.push(base[k])
    for (let k = c.sideStart; k < c.sideEnd; k++) result.push(c.sideLines[k - c.sideStart])
    pos = c.baseEnd
  }
  for (let k = pos; k < end; k++) result.push(base[k])
  return result
}

/**
 * Merge `mine`, `base` and `theirs` (arrays of strings) into a list of
 * segments, plus whether any conflict was produced.
 *
 * Each segment is one of:
 *   { type: 'stable', lines }
 *   { type: 'mine', lines }
 *   { type: 'theirs', lines }
 *   { type: 'both', lines }
 *   { type: 'conflict', mine, base, theirs }
 */
export function mergeDocuments(mine, base, theirs) {
  const mineChanges = diffAgainstBase(mine, base).map(c => ({
    ...c,
    side: 'mine',
    sideLines: mine.slice(c.sideStart, c.sideEnd),
  }))
  const theirChanges = diffAgainstBase(theirs, base).map(c => ({
    ...c,
    side: 'theirs',
    sideLines: theirs.slice(c.sideStart, c.sideEnd),
  }))

  const allChanges = mineChanges.concat(theirChanges).sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let k = 0
  while (k < allChanges.length) {
    const region = { start: allChanges[k].baseStart, end: allChanges[k].baseEnd, changes: [allChanges[k]] }
    k++
    while (k < allChanges.length && allChanges[k].baseStart <= region.end) {
      region.changes.push(allChanges[k])
      if (allChanges[k].baseEnd > region.end) region.end = allChanges[k].baseEnd
      k++
    }
    regions.push(region)
  }

  const segments = []
  let conflict = false
  let pos = 0

  for (const region of regions) {
    if (region.start > pos) {
      segments.push({ type: 'stable', lines: base.slice(pos, region.start) })
    }

    const regionMine = region.changes.filter(c => c.side === 'mine')
    const regionTheirs = region.changes.filter(c => c.side === 'theirs')

    const mineLines = sideContribution(region.start, region.end, base, regionMine)
    const theirLines = sideContribution(region.start, region.end, base, regionTheirs)
    const baseLines = base.slice(region.start, region.end)

    if (arraysEqual(mineLines, theirLines)) {
      segments.push({ type: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      segments.push({ type: 'theirs', lines: theirLines })
    } else if (arraysEqual(theirLines, baseLines)) {
      segments.push({ type: 'mine', lines: mineLines })
    } else {
      segments.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirLines })
      conflict = true
    }

    pos = region.end
  }

  if (pos < base.length) {
    segments.push({ type: 'stable', lines: base.slice(pos) })
  }

  return { segments, conflict }
}
"}

