{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { mergeDocuments } from './merge.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function parseInput(raw) {
  let lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }

  if (docs.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }

  return docs
}

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const raw = readStdinSync()
  const [mine, base, theirs] = parseInput(raw)

  const { segments, conflict } = mergeDocuments(mine, base, theirs)

  const outLines = []
  if (mode === 'regions') {
    for (const seg of segments) {
      if (seg.type === 'conflict') {
        outLines.push(`conflict mine=${seg.mine.length} base=${seg.base.length} theirs=${seg.theirs.length}`)
      } else {
        outLines.push(`${seg.type} ${seg.lines.length}`)
      }
    }
  } else {
    for (const seg of segments) {
      if (seg.type === 'conflict') {
        outLines.push('<<<<<<< mine')
