 * Parser for the configuration document format described in the task.
 *
 * Produces a tree of nodes:
 *   { kind: 'table', entries: Map<string, node>, headerDefined: boolean }
 *   { kind: 'arrayoftables', items: [tableNode, ...] }
 *   { kind: 'array', items: [node, ...] }
 *   { kind: 'string', value: string }
 *   { kind: 'integer', value: bigint }
 *   { kind: 'float', value: number }
 *   { kind: 'boolean', value: boolean }
 */

export class DocError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

class LineError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/

function fullPathStr(path) {
  return path.join('.')
}

function newTable(headerDefined) {
  return { kind: 'table', entries: new Map(), headerDefined }
}

class Parser {
  constructor(line) {
    this.line = line
    this.pos = 0
    this.len = line.length
  }

  atEnd() {
    return this.pos >= this.len
  }

  peek() {
    return this.line[this.pos]
  }

  err(reason) {
    throw new LineError(reason)
  }

  skipWS() {
    while (this.pos < this.len && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  // Skip whitespace, and if a comment follows, jump to end of line.
  skipWSC() {
    this.skipWS()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) {
      this.pos = this.len
    }
  }

  parseName() {
    this.skipWS()
    if (this.atEnd()) this.err('expected a name')
    const c = this.peek()
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    if (NAME_CHAR.test(c)) {
      const start = this.pos
      while (this.pos < this.len && NAME_CHAR.test(this.line[this.pos])) this.pos++
      return this.line.slice(start, this.pos)
    }
    this.err('expected a name')
  }

  parseDottedName() {
    const parts = [this.parseName()]
    while (true) {
      this.skipWS()
      if (!this.atEnd() && this.peek() === '.') {
        this.pos++
        this.skipWS()
        parts.push(this.parseName())
      } else {
        break
      }
    }
    return parts
  }

  parseBasicString() {
    // pos at opening quote
    this.pos++
    let out = ''
    while (true) {
      if (this.atEnd()) this.err('unterminated string')
      const c = this.line[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.atEnd()) this.err('unterminated string')
        const e = this.line[this.pos]
        switch (e) {
          case '"':
            out += '"'
            this.pos++
            break
          case '\\':
            out += '\\'
            this.pos++
            break
          case 'n':
            out += '\n'
            this.pos++
            break
          case 't':
            out += '\t'
            this.pos++
            break
          case 'r':
            out += '\r'
            this.pos++
            break
          case '0':
            out += '\0'
            this.pos++
            break
          case 'u': {
            this.pos++
            if (this.pos + 4 > this.len) this.err('unterminated string')
            const hex = this.line.slice(this.pos, this.pos + 4)
            if (!/^[0-9A-Fa-f]{4}$/.test(hex)) this.err('invalid escape \\u')
            out += String.fromCharCode(parseInt(hex, 16))
            this.pos += 4
            break
          }
          default:
            this.err(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  parseLiteralString() {
    this.pos++
    const start = this.pos
    while (true) {
      if (this.atEnd()) this.err('unterminated string')
      if (this.line[this.pos] === "'") {
        const out = this.line.slice(start, this.pos)
        this.pos++
        return out
      }
      this.pos++
    }
  }

  parseValue(pathPrefix) {
    this.skipWSC()
    if (this.atEnd()) this.err('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') this.err('expected a value')
    if (c === '"') return { kind: 'string', value: this.parseBasicString() }
    if (c === "'") return { kind: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArray(pathPrefix)
    if (c === '{') return this.parseInlineTable(pathPrefix)

    const start = this.pos
    while (this.pos < this.len) {
      const ch = this.line[this.pos]
      if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
      this.pos++
    }
    const text = this.line.slice(start, this.pos)
    if (text === '') this.err('expected a value')
    if (text === 'true') return { kind: 'boolean', value: true }
    if (text === 'false') return { kind: 'boolean', value: false }
    if (/^[+-]?\d+(_\d+)*$/.test(text)) {
      return { kind: 'integer', value: BigInt(text.replace(/_/g, '')) }
    }
    const floatWithFrac = /^[+-]?\d+(_\d+)*\.\d+(_\d+)*([eE][+-]?\d+(_\d+)*)?$/
    const floatExpOnly = /^[+-]?\d+(_\d+)*[eE][+-]?\d+(_\d+)*$/
    if (floatWithFrac.test(text) || floatExpOnly.test(text)) {
      return { kind: 'float', value: Number(text.replace(/_/g, '')) }
    }
    this.err(`invalid value ${text}`)
  }

  parseArray(pathPrefix) {
    this.pos++ // consume '['
    const items = []
    this.skipWSC()
    if (this.atEnd()) this.err('unterminated array')
    if (this.peek() === ']') {
      this.pos++
      return { kind: 'array', items }
    }
    while (true) {
      const v = this.parseValue(pathPrefix)
      items.push(v)
      this.skipWSC()
      if (this.atEnd()) this.err('unterminated array')
      if (this.peek() === ',') {
        this.pos++
        this.skipWSC()
        if (this.atEnd()) this.err('unterminated array')
        if (this.peek() === ']') {
          this.pos++
          return { kind: 'array', items }
        }
        continue
      }
      if (this.peek() === ']') {
        this.pos++
        return { kind: 'array', items }
      }
      this.err('unterminated array')
    }
  }

  parseInlineTable(pathPrefix) {
    this.pos++ // consume '{'
    const table = newTable(false)
    this.skipWSC()
    if (this.atEnd()) this.err('unterminated inline table')
    if (this.peek() === '}') {
      this.pos++
      return table
    }
    while (true) {
      const parts = this.parseDottedName()
      this.skipWSC()
      if (this.atEnd()) this.err('unterminated inline table')
      if (this.peek() !== '=') this.err('expected = in an inline table')
      this.pos++
      this.skipWSC()
      this.assignKeyValue(table, pathPrefix, parts)
      this.skipWSC()
      if (this.atEnd()) this.err('unterminated inline table')
      if (this.peek() === ',') {
        this.pos++
        this.skipWSC()
        if (this.atEnd()) this.err('unterminated inline table')
        continue
      }
      if (this.peek() === '}') {
        this.pos++
        return table
      }
      this.err('unterminated inline table')
    }
  }

  // Walks/creates intermediate tables for parts[0..-2], then assigns the
  // value parsed at the current position into parts[-1]. pos must be
  // positioned at the start of the value (after '=' and whitespace).
  assignKeyValue(container, pathPrefix, parts) {
    let table = container
    const path = pathPrefix.slice()
    for (let i = 0; i < parts.length - 1; i++) {
      const name = parts[i]
      path.push(name)
      const existing = table.entries.get(name)
      if (existing === undefined) {
        const t = newTable(false)
        table.entries.set(name, t)
        table = t
      } else if (existing.kind === 'table') {
        table = existing
      } else if (existing.kind === 'arrayoftables') {
        table = existing.items[existing.items.length - 1]
      } else {
        this.err(`${fullPathStr(path)} is not a table`)
      }
    }
    const lastName = parts[parts.length - 1]
    const fullPath = path.concat(lastName)
    if (table.entries.has(lastName)) {
      this.err(`key ${fullPathStr(fullPath)} is defined twice`)
    }
    const value = this.parseValue(fullPath)
    table.entries.set(lastName, value)
    return value
  }

  parseHeaderLine(ctx) {
    this.pos++ // consume first '['
    let isArray = false
    if (!this.atEnd() && this.peek() === '[') {
      isArray = true
      this.pos++
    }
    const parts = this.parseDottedName()
    this.skipWS()
    if (this.atEnd() || this.peek() !== ']') this.err('unterminated table header')
    this.pos++
    if (isArray) {
      if (this.atEnd() || this.peek() !== ']') this.err('unterminated table header')
      this.pos++
    }
    this.skipWS()
    if (!this.atEnd() && this.peek() !== '#' && this.peek() !== ';') {
      this.err('trailing text after a table header')
    }

    let table = ctx.current.root
    const path = []
    for (let i = 0; i < parts.length - 1; i++) {
      const name = parts[i]
      path.push(name)
      const existing = table.entries.get(name)
      if (existing === undefined) {
        const t = newTable(false)
        table.entries.set(name, t)
        table = t
      } else if (existing.kind === 'table') {
        table = existing
      } else if (existing.kind === 'arrayoftables') {
        table = existing.items[existing.items.length - 1]
      } else {
        this.err(`${fullPathStr(path)} is not a table`)
      }
    }
    const lastName = parts[parts.length - 1]
    const fullPath = path.concat(lastName)

    if (!isArray) {
      const existing = table.entries.get(lastName)
      if (existing === undefined) {
        const t = newTable(true)
        table.entries.set(lastName, t)
        ctx.current.table = t
        ctx.current.path = fullPath
      } else if (existing.kind === 'table') {
        if (existing.headerDefined) this.err(`table ${fullPathStr(fullPath)} is defined twice`)
        existing.headerDefined = true
        ctx.current.table = existing
        ctx.current.path = fullPath
      } else {
        this.err(`${fullPathStr(fullPath)} is not a table`)
      }
    } else {
      const existing = table.entries.get(lastName)
      let arr
      if (existing === undefined) {
        arr = { kind: 'arrayoftables', items: [] }
        table.entries.set(lastName, arr)
      } else if (existing.kind === 'arrayoftables') {
        arr = existing
      } else {
        this.err(`${fullPathStr(fullPath)} is not an array of tables`)
      }
      const t = newTable(true)
      arr.items.push(t)
      ctx.current.table = t
      ctx.current.path = fullPath
    }
  }
}

function processLine(line, ctx) {
  const p = new Parser(line)
  p.skipWS()
  if (p.atEnd()) return
  if (p.peek() === '#' || p.peek() === ';') return
  if (p.peek() === '[') {
    p.parseHeaderLine(ctx)
    return
  }
  const parts = p.parseDottedName()
  p.skipWS()
  if (p.atEnd() || p.peek() !== '=') p.err('expected key = value')
  p.pos++
  p.skipWSC()
  p.assignKeyValue(ctx.current.table, ctx.current.path, parts)
  p.skipWSC()
  if (!p.atEnd()) p.err('trailing text after a value')
}

export function parseDocument(text) {
  const rawLines = text.split('\n')
  if (rawLines.length && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const root = newTable(true)
  const ctx = { current: { root, table: root, path: [] } }

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    try {
      processLine(rawLines[i], ctx)
    } catch (e) {
      if (e instanceof LineError) {
        throw new DocError(lineNo, e.reason)
      }
      throw e
    }
  }

  return root
}
"}

