function cmpCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(entries) {
  return [...entries.keys()].sort(cmpCodePoint)
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array':
    case 'arrayoftables':
      return 'array'
    default:
      return node.kind
  }
}

function printJSON(node, indent) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.entries)
      if (keys.length === 0) return '{}'
      const childIndent = indent + '  '
      const inner = keys
        .map((k) => `${childIndent}${JSON.stringify(k)}: ${printJSON(node.entries.get(k), childIndent)}`)
        .join(',\n')
      return `{\n${inner}\n${indent}}`
    }
    case 'array':
    case 'arrayoftables': {
      if (node.items.length === 0) return '[]'
      const childIndent = indent + '  '
      const inner = node.items.map((it) => `${childIndent}${printJSON(it, childIndent)}`).join(',\n')
      return `[\n${inner}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return printJSON(root, '') + '\n'
}

function emitChildren(node, basePath, out) {
  if (node.kind === 'table') {
    const keys = sortedKeys(node.entries)
    for (const k of keys) {
      const child = node.entries.get(k)
      const path = basePath === '' ? k : `${basePath}.${k}`
      out.push(`${path} ${typeName(child)}`)
      emitChildren(child, path, out)
    }
  } else if (node.kind === 'array' || node.kind === 'arrayoftables') {
    node.items.forEach((child, i) => {
      const path = `${basePath}[${i}]`
      out.push(`${path} ${typeName(child)}`)
      emitChildren(child, path, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  emitChildren(root, '', out)
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
"}

