      for (const dependent of dependents.get(chosen) || []) {
        const remaining = indegree.get(dependent) - 1
        indegree.set(dependent, remaining)
        if (remaining === 0) {
          let readyAt = 0
          for (const dep of deps.get(dependent) || []) {
            const f = finishTime.get(dep)
            if (f > readyAt) readyAt = f
          }
          pendingReady.set(dependent, readyAt)
        }
      }
    }

    if (unfinished === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > time && workerFreeAt[i] < next) next = workerFreeAt[i]
    }
    if (next === Infinity) {
      // Should not happen for a valid DAG, but avoid looping forever.
      break
    }
    time = next
