{"file_path":"src/pack.js","content":"import { buildDependents, computePriority } from './graph.js'

/**
 * Simulates the build graph on a fixed number of workers using a greedy
 * priority scheduler. Returns { logs, makespan } where logs is an array
 * (one per worker) of { name, start, finish } entries in run order.
 */
export function packSchedule(tasks, depsMap, workerCount) {
  const dependents = buildDependents(tasks, depsMap)
  const priority = computePriority(tasks, dependents)

  const names = [...tasks.keys()]
  const inDegree = new Map()
  for (const name of names) inDegree.set(name, (depsMap.get(name) || new Set()).size)

  const ready = []
  for (const name of names) if (inDegree.get(name) === 0) ready.push(name)

  const freeAt = new Array(workerCount).fill(0)
  const logs = Array.from({ length: workerCount }, () => [])
  const pendingFinish = []
  let currentTime = 0
  let startedCount = 0
  const totalTasks = names.length

  function processFinish(name) {
    for (const dep of dependents.get(name) || []) {
      inDegree.set(dep, inDegree.get(dep) - 1)
      if (inDegree.get(dep) === 0) ready.push(dep)
    }
  }

  function popBestReady() {
    let bestIdx = -1
    for (let i = 0; i < ready.length; i++) {
      if (bestIdx === -1) {
        bestIdx = i
        continue
      }
      const a = ready[i]
      const b = ready[bestIdx]
      const pa = priority.get(a)
      const pb = priority.get(b)
      if (pa > pb || (pa === pb && a < b)) bestIdx = i
    }
    const name = ready[bestIdx]
    ready.splice(bestIdx, 1)
    return name
  }

  while (startedCount < totalTasks || pendingFinish.length) {
    for (let i = pendingFinish.length - 1; i >= 0; i--) {
      if (pendingFinish[i].time === currentTime) {
        processFinish(pendingFinish[i].name)
        pendingFinish.splice(i, 1)
      }
    }

    let progressed = true
    while (progressed) {
      progressed = false
      let w = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= currentTime) {
          w = i
          break
        }
      }
      if (w === -1 || ready.length === 0) break

      const name = popBestReady()
      const start = currentTime
      const finish = start + tasks.get(name)
      logs[w].push({ name, start, finish })
      freeAt[w] = finish
      startedCount++
      if (finish === currentTime) {
        processFinish(name)
      } else {
        pendingFinish.push({ time: finish, name })
      }
      progressed = true
    }

    if (startedCount === totalTasks && pendingFinish.length === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (freeAt[i] > currentTime) next = Math.min(next, freeAt[i])
    }
    if (next === Infinity) break
    currentTime = next
  }

  let makespan = 0
  for (const log of logs) {
    for (const entry of log) makespan = Math.max(makespan, entry.finish)
  }

  return { logs, makespan }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import fs from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkCycle, computeSchedule } from './graph.js'
import { packSchedule } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function runWaves(tasks, depsMap) {
  const { finish, wave } = computeSchedule(tasks, depsMap)
  const names = [...tasks.keys()].sort()
  let maxWave = -1
  let total = 0
  const byWave = new Map()
  for (const name of names) {
    const w = wave.get(name)
    maxWave = Math.max(maxWave, w)
    if (!byWave.has(w)) byWave.set(w, [])
    byWave.get(w).push(name)
    total = Math.max(total, finish.get(name))
  }
  const lines = []
  for (let w = 0; w <= maxWave; w++) {
    const group = (byWave.get(w) || []).slice().sort()
    lines.push(`wave ${w}: ${group.join(' ')}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runExplain(tasks, depsMap) {
  const { start, finish, wave } = computeSchedule(tasks, depsMap)
  const names = [...tasks.keys()].sort()
  let total = 0
  const lines = []
  for (const name of names) {
    total = Math.max(total, finish.get(name))
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${wave.get(name)}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runPack(tasks, depsMap, workers) {
  const { logs, makespan } = packSchedule(tasks, depsMap, workers)
  const lines = []
  for (let i = 0; i < workers; i++) {
    const entries = logs[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = readStdin()
  const { tasks, depsMap } = parseGraph(input)
  checkCycle(tasks, depsMap)

  if (mode === 'waves') runWaves(tasks, depsMap)
  else if (mode === 'explain') runExplain(tasks, depsMap)
  else runPack(tasks, depsMap, workers)
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  }
  throw err
}
"}

