{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function formatRoundLine(roundNumber, counts, exhausted) {
  const entries = [...counts.entries()]
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  return `round ${roundNumber}: ${parts.join(' ')} exhausted=${exhausted}`
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  let input
  try {
    input = readStdin()
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(err.message + '\n')
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      out.push(formatRoundLine(i + 1, round.counts, round.exhausted))
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(out.join('\n') + '\n')
  process.exit(0)
}

main()
"}

