{"file_path":"src/format.js","content":"function jsonValue(node, indentLevel) {
  const pad = '  '.repeat(indentLevel)
  const padIn = '  '.repeat(indentLevel + 1)
  switch (node.t) {
    case 'string':
      return JSON.stringify(node.v)
    case 'integer':
    case 'float':
      return JSON.stringify(node.v)
    case 'boolean':
      return node.v ? 'true' : 'false'
    case 'table': {
      const keys = [...node.map.keys()].sort()
      if (keys.length === 0) return '{}'
      const lines = keys.map(
        (k) => `${padIn}${JSON.stringify(k)}: ${jsonValue(node.map.get(k), indentLevel + 1)}`
      )
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'array':
    case 'aot': {
      if (node.items.length === 0) return '[]'
      const lines = node.items.map((it) => `${padIn}${jsonValue(it, indentLevel + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    default:
      throw new Error(`unknown node type ${node.t}`)
  }
}

export function toJson(root) {
  return jsonValue(root, 0) + '\n'
}

function typeOf(node) {
  switch (node.t) {
    case 'table':
      return 'table'
    case 'array':
    case 'aot':
      return 'array'
    case 'string':
      return 'string'
    case 'integer':
      return 'integer'
    case 'float':
      return 'float'
    case 'boolean':
      return 'boolean'
    default:
      throw new Error(`unknown node type ${node.t}`)
  }
}

function collectKeys(node, path, out) {
  if (node.t === 'table') {
    const keys = [...node.map.keys()].sort()
    for (const k of keys) {
      const child = node.map.get(k)
      const childPath = path ? `${path}.${k}` : k
      out.push(`${childPath} ${typeOf(child)}`)
      collectKeys(child, childPath, out)
    }
  } else if (node.t === 'array' || node.t === 'aot') {
    node.items.forEach((it, idx) => {
      const childPath = `${path}[${idx}]`
      out.push(`${childPath} ${typeOf(it)}`)
      collectKeys(it, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  collectKeys(root, '', out)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

