  let query = null
  const qIdx = rest.indexOf('?')
  if (qIdx !== -1) {
    hasQuery = true
    query = rest.slice(qIdx + 1)
    rest = rest.slice(0, qIdx)
  }

  let scheme = null
  const colonIdx = rest.indexOf(':')
  const slashIdx = rest.indexOf('/')
  if (colonIdx !== -1 && (slashIdx === -1 || slashIdx > colonIdx)) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let hasAuthority = false
  let userinfo = null
  let host = ''
  let port = null
  if (rest.startsWith('//')) {
    hasAuthority = true
    const afterSlashes = rest.slice(2)
    const endIdx = afterSlashes.indexOf('/')
    let authStr
    if (endIdx === -1) {
      authStr = afterSlashes
      rest = ''
    } else {
      authStr = afterSlashes.slice(0, endIdx)
      rest = afterSlashes.slice(endIdx)
