export function NumVal(n) {
  return { kind: 'num', value: n }
}
export function TextVal(s) {
  return { kind: 'text', value: s }
}
export function BoolVal(b) {
  return { kind: 'bool', value: b }
}
export function ErrVal(token) {
  return { kind: 'err', value: token }
}

/** Read a value as a number for arithmetic. Returns a number, or an ErrVal. */
export function toNum(v) {
  if (v.kind === 'num') return v.value
  if (v.kind === 'bool') return v.value ? 1 : 0
  if (v.kind === 'text') return ErrVal('#VALUE!')
  return v // already an error
}

const RANK = { num: 0, text: 1, bool: 2 }

export function compareValues(a, b) {
  if (RANK[a.kind] !== RANK[b.kind]) return RANK[a.kind] - RANK[b.kind]
  if (a.kind === 'num') return a.value - b.value
  if (a.kind === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  // bool
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av - bv
