{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-b4GHCY/src/evaluate.js","content":"import { parseFormula, ParseError } from './parser.js'
import { parseAddress, numToCol, compareAddresses } from './address.js'
import { NumVal, TextVal, BoolVal, ErrVal, ERROR_TOKENS, toNum, compareValues } from './values.js'

const LITERAL_NUM_RE = /^-?[0-9]+(\.[0-9]+)?$/

/**
 * Build an evaluator bound to a parsed sheet (Map from canonical address to
 * { content, col, row }). Formulas are parsed lazily and cached.
 */
export function makeEvaluator(cells) {
  const astCache = new Map() // address -> ast | null (null = parse failure) | undefined (not a formula)
  const memo = new Map() // address -> Value
  const stack = new Set()

  function getAst(addr) {
    if (astCache.has(addr)) return astCache.get(addr)
    const cell = cells.get(addr)
    let ast
    if (cell === undefined || !cell.content.startsWith('=')) {
      ast = undefined
    } else {
      try {
        ast = parseFormula(cell.content.slice(1))
      } catch (e) {
        if (e instanceof ParseError) ast = null
        else throw e
      }
    }
    astCache.set(addr, ast)
    return ast
  }

  function literalValue(content) {
    if (content === '') return NumVal(0)
    if (LITERAL_NUM_RE.test(content)) return NumVal(parseFloat(content))
    if (ERROR_TOKENS.has(content)) return ErrVal(content)
    return TextVal(content)
  }

  function evaluateCell(addr) {
    if (memo.has(addr)) return memo.get(addr)
    if (stack.has(addr)) return ErrVal('#CYCLE!')
    const cell = cells.get(addr)
    if (cell === undefined) {
      const v = NumVal(0)
      memo.set(addr, v)
      return v
    }
    stack.add(addr)
    let result
    if (!cell.content.startsWith('=')) {
      result = literalValue(cell.content)
    } else {
      const ast = getAst(addr)
      if (ast === null) {
        result = ErrVal('#ERR!')
      } else {
        result = evalNode(ast)
      }
    }
    stack.delete(addr)
    memo.set(addr, result)
    return result
  }

  function expandRange(node) {
    const a = parseAddress(node.from)
    const b = parseAddress(node.to)
    if (!a.valid || !b.valid) return null
    const c1 = Math.min(a.col, b.col)
    const c2 = Math.max(a.col, b.col)
    const r1 = Math.min(a.row, b.row)
    const r2 = Math.max(a.row, b.row)
    const out = []
    for (let c = c1; c <= c2; c++) {
      for (let r = r1; r <= r2; r++) {
        out.push(`${numToCol(c)}${r}`)
      }
    }
    return out
  }

  // Evaluate a list of argument nodes (range or expr), expanding ranges.
  // Returns { values, firstError }. Stops scanning once an error is found.
  function evalArgs(argNodes) {
    let firstError = null
    const values = []
    for (const node of argNodes) {
      if (node.type === 'range') {
        const addrs = expandRange(node)
        if (addrs === null) {
          const ev = ErrVal('#REF!')
          values.push(ev)
          if (!firstError) firstError = ev
          continue
        }
        for (const a of addrs) {
          const v = evaluateCell(a)
          values.push(v)
          if (v.kind === 'err' && !firstError) firstError = v
        }
      } else {
        const v = evalNode(node)
        values.push(v)
        if (v.kind === 'err' && !firstError) firstError = v
      }
    }
    return { values, firstError }
  }

  function evalOneArg(node) {
    const { values, firstError } = evalArgs([node])
    if (firstError) return firstError
    return values[0]
  }

  function numOf(v) {
    if (v.kind === 'num') return v.value
    if (v.kind === 'bool') return v.value ? 1 : 0
    return null
  }

  function evalCall(node) {
    const name = node.name
    if (name === 'IF') {
      if (node.args.length !== 3) return ErrVal('#ERR!')
      const [condNode, thenNode, elseNode] = node.args
      const condVal = evalOneArg(condNode)
      if (condVal.kind === 'err') return condVal
      let truthy
      if (condVal.kind === 'bool') truthy = condVal.value
      else if (condVal.kind === 'num') truthy = condVal.value !== 0
      else return ErrVal('#VALUE!')
      return truthy ? evalOneArg(thenNode) : evalOneArg(elseNode)
    }

    const { values, firstError } = evalArgs(node.args)
    if (firstError) return firstError

    switch (name) {
      case 'SUM': {
        if (node.args.length < 1) return ErrVal('#ERR!')
        let total = 0
        for (const v of values) {
          const n = numOf(v)
          if (n === null) return ErrVal('#VALUE!')
          total += n
        }
        if (!Number.isFinite(total)) return ErrVal('#DIV/0!')
        return NumVal(total)
      }
      case 'MIN':
      case 'MAX': {
        if (node.args.length < 1) return ErrVal('#ERR!')
        let best = null
        for (const v of values) {
          const n = numOf(v)
          if (n === null) return ErrVal('#VALUE!')
          if (best === null) best = n
          else best = name === 'MIN' ? Math.min(best, n) : Math.max(best, n)
        }
        return NumVal(best)
      }
      case 'AVG': {
        if (node.args.length < 1) return ErrVal('#ERR!')
        let total = 0
        for (const v of values) {
          const n = numOf(v)
          if (n === null) return ErrVal('#VALUE!')
          total += n
        }
        const avg = total / values.length
        if (!Number.isFinite(avg)) return ErrVal('#DIV/0!')
        return NumVal(avg)
      }
      case 'COUNT': {
        if (node.args.length < 1) return ErrVal('#ERR!')
        let c = 0
        for (const v of values) {
          if (v.kind === 'num') c++
        }
        return NumVal(c)
      }
      case 'ABS': {
        if (node.args.length !== 1) return ErrVal('#ERR!')
