/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalizeComponents, resolveComponents, render, UriError } from './uri.js'

function readStdin() {
  const chunks = []
  process.stdin.on('data', (chunk) => chunks.push(chunk))
  return new Promise((resolve, reject) => {
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function splitRecords(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function processRecord(mode, record, lineNumber) {
  if (mode === 'normalize') {
    const ref = parseReference(record)
    const normalized = normalizeComponents(ref)
    return render(normalized)
  }

  const spaceIndex = record.indexOf(' ')
  if (spaceIndex === -1) {
    throw new UriError(`expected a base and a reference`, true)
  }
  const baseStr = record.slice(0, spaceIndex)
  const refStr = record.slice(spaceIndex + 1)

  const base = parseReference(baseStr)
  if (base.scheme === null) {
    throw new UriError(`the base has no scheme`, true)
  }

  const ref = parseReference(refStr)
  const resolved = resolveComponents(base, ref)
  return render(resolved)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]

  const text = await readStdin()
  const records = splitRecords(text)

  const results = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    try {
      results.push(processRecord(mode, records[i], lineNumber))
    } catch (err) {
      if (err instanceof UriError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
        process.exit(2)
      }
      throw err
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

