 * Longest common subsequence alignment between a base document and another
 * document, with a deterministic tie-break: walking both documents from the
 * start, take a match whenever the two current lines are equal, and
 * otherwise advance the side whose remaining subsequence is at least as
 * long as the other's, preferring to advance the base when they tie.
 *
 * Returns a list of [baseIndex, otherIndex] pairs, strictly increasing in
 * both coordinates.
 */
export function align(base, other) {
  const m = base.length
  const n = other.length
  // dp[i][j] = length of the LCS of base[i:] and other[j:]
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    const row = dp[i]
    const nextRow = dp[i + 1]
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === other[j]) {
        row[j] = nextRow[j + 1] + 1
      } else {
        const advanceBase = nextRow[j]
        const advanceOther = row[j + 1]
        row[j] = advanceBase >= advanceOther ? advanceBase : advanceOther
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === other[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advanceBase = dp[i + 1][j]
      const advanceOther = dp[i][j + 1]
      if (advanceBase >= advanceOther) {
        i++
      } else {
        j++
      }
    }
  }
  return matches
}

/**
 * Turns an alignment into a list of changes: stretches of the base document
 * replaced by stretches of the other document. baseStart/baseEnd are
 * indices into base (end exclusive); lines are the other document's lines
 * for that stretch.
 */
export function changesFromMatches(base, other, matches) {
  const changes = []
  let bi = 0
  let oj = 0
  for (const [mi, mj] of matches) {
    if (mi > bi || mj > oj) {
      changes.push({ baseStart: bi, baseEnd: mi, lines: other.slice(oj, mj) })
    }
    bi = mi + 1
    oj = mj + 1
  }
  if (bi < base.length || oj < other.length) {
    changes.push({ baseStart: bi, baseEnd: base.length, lines: other.slice(oj, other.length) })
  }
  return changes
}

export function computeChanges(base, other) {
  return changesFromMatches(base, other, align(base, other))
}
"}

