/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { buildSegments } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function parseDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const groups = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      groups.push([])
    } else {
      groups[groups.length - 1].push(line)
    }
  }

  if (groups.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }
  return groups
}

function main() {
  if (process.argv.length !== 3 || !MODES.has(process.argv[2])) {
    fail('error: usage: cli.js merge|merge2|regions')
  }
  const mode = process.argv[2]

  const input = readFileSync(0, 'utf8')
  const [mine, base, theirs] = parseDocuments(input)

  const segments = buildSegments(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const segment of segments) {
      switch (segment.type) {
        case 'stable':
          out.push(`stable ${segment.lines.length}`)
          break
        case 'mine':
          out.push(`mine ${segment.mine.length}`)
          break
        case 'theirs':
          out.push(`theirs ${segment.theirs.length}`)
          break
        case 'both':
          out.push(`both ${segment.mine.length}`)
          break
        case 'conflict':
          conflict = true
          out.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`)
          break
      }
    }
  } else {
    const withBase = mode === 'merge'
    for (const segment of segments) {
      switch (segment.type) {
        case 'stable':
          out.push(...segment.lines)
          break
        case 'mine':
          out.push(...segment.mine)
          break
        case 'theirs':
          out.push(...segment.theirs)
          break
        case 'both':
          out.push(...segment.mine)
          break
        case 'conflict':
          conflict = true
          out.push('<<<<<<< mine')
          out.push(...segment.mine)
          if (withBase) {
            out.push('||||||| base')
            out.push(...segment.base)
          }
          out.push('=======')
          out.push(...segment.theirs)
          out.push('>>>>>>> theirs')
          break
      }
    }
  }

  const text = out.length === 0 ? '' : out.map(line => `${line}\n`).join('')
  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

