 * Parses election text into a list of candidate names (in declaration order)
 * and a list of ballots ({ count, candidates }). Throws a ParseError carrying
 * the 1-based line number (or null for the no-candidates case) and a message.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

function fail(line, message) {
  throw new ParseError(line, message)
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null // array of names, in order
  let candidateSet = null // Set of names
  const ballots = []

  lines.forEach((raw, idx) => {
    const lineNo = idx + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        fail(lineNo, 'expected candidates <name>...')
      }
      candidates = []
      candidateSet = new Set()
      for (let i = 1; i < tokens.length; i++) {
        const name = tokens[i]
        if (!NAME_RE.test(name)) {
          fail(lineNo, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          fail(lineNo, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      return
    }

    if (directive === 'ballot') {
      if (candidates === null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        fail(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        fail(lineNo, 'count must be a positive integer')
      }
      const count = Number(countToken)
      const seen = new Set()
      const names = []
      for (let i = 2; i < tokens.length; i++) {
        const name = tokens[i]
        if (!candidateSet.has(name)) {
          fail(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count, candidates: names })
      return
    }

    fail(lineNo, `unknown directive ${directive}`)
  })

  if (candidates === null || candidates.length === 0) {
    fail(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

