/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { countRounds } from './count.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function formatRound(index, round) {
  const entries = [...round.votes.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${index + 1}: ${parts.join(' ')}`
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = require('node:fs').readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const prefix = err.line === null ? 'error: ' : `error: line ${err.line}: `
      process.stderr.write(`${prefix}${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = countRounds(election.candidates, election.ballots)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      lines.push(formatRound(index, round))
      if (round.eliminated) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(winner ? `winner ${winner}` : 'no winner')

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

