 * or the summary lines for the given mode. Throws a ParseError on the
 * first malformed line, with nothing yet written to standard output.
 */

import { Bucket, Window } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const FIELD_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function parseField(str, fieldName, least, line) {
  if (!FIELD_RE.test(str)) fail(line, `${fieldName} must be an integer of at least ${least}`)
  const value = BigInt(str)
  if (value < least) fail(line, `${fieldName} must be an integer of at least ${least}`)
  return value
}

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Runs the whole file and returns { replayLines, summary } where
 * replayLines is an array of `<tick> <key> allow|deny <policy>` strings
 * in log order, and summary is { perKey: Map<key, {allowed,denied}>,
 * totalAllowed, totalDenied } with BigInt counters.
 */
export function simulate(input) {
  const lines = splitLines(input)
  const policies = new Map()
  const routes = []
  let firstEventSeen = false
  let lastTick = null

  const replayLines = []
  const perKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive !== 'bucket' && directive !== 'window' && directive !== 'route' && directive !== 'event') {
      fail(lineNum, `unknown directive ${directive}`)
    }

    if (directive === 'event') {
      firstEventSeen = true
      if (tokens.length !== 3) fail(lineNum, 'expected event <tick> <key>')
      const [, tickStr, key] = tokens
      const tick = parseField(tickStr, 'tick', 0n, lineNum)
      if (!NAME_RE.test(key)) fail(lineNum, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) fail(lineNum, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick

      const route = findRoute(routes, key)
      let allowed = true
      let denyPolicy = null
      if (route) {
        for (const pname of route.policyNames) {
          policies.get(pname).advance(key, tick)
        }
        for (const pname of route.policyNames) {
          if (!policies.get(pname).allow(key)) {
            allowed = false
            denyPolicy = pname
            break
          }
        }
        if (allowed) {
          for (const pname of route.policyNames) {
            policies.get(pname).record(key, tick)
          }
        }
      }

      let stat = perKey.get(key)
      if (!stat) {
        stat = { allowed: 0n, denied: 0n }
        perKey.set(key, stat)
      }
      if (allowed) {
        stat.allowed++
        totalAllowed++
        replayLines.push(`${tick} ${key} allow`)
      } else {
        stat.denied++
        totalDenied++
        replayLines.push(`${tick} ${key} deny ${denyPolicy}`)
      }
      continue
    }

    if (firstEventSeen) fail(lineNum, 'declarations must come before the first event')

    if (directive === 'bucket') {
      if (tokens.length !== 5) fail(lineNum, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capStr, refillStr, perStr] = tokens
      if (!NAME_RE.test(name)) fail(lineNum, `invalid policy name ${name}`)
      const capacity = parseField(capStr, 'capacity', 1n, lineNum)
      const refill = parseField(refillStr, 'refill', 0n, lineNum)
      const per = parseField(perStr, 'per', 1n, lineNum)
      if (policies.has(name)) fail(lineNum, `policy ${name} is declared twice`)
      policies.set(name, new Bucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) fail(lineNum, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
      if (!NAME_RE.test(name)) fail(lineNum, `invalid policy name ${name}`)
      const limit = parseField(limitStr, 'limit', 0n, lineNum)
      const span = parseField(spanStr, 'span', 1n, lineNum)
      if (policies.has(name)) fail(lineNum, `policy ${name} is declared twice`)
      policies.set(name, new Window(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) fail(lineNum, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!NAME_RE.test(prefix)) fail(lineNum, `invalid route prefix ${prefix}`)
      for (const pname of policyNames) {
        if (!policies.has(pname)) fail(lineNum, `unknown policy ${pname}`)
      }
      if (routes.some((r) => r.prefix === prefix)) fail(lineNum, `prefix ${prefix} is routed twice`)
      routes.push({ prefix, policyNames })
    }
  }

  return { replayLines, summary: { perKey, totalAllowed, totalDenied } }
}
"}

