 * Simulates the build graph on a fixed number of workers, greedily starting
 * the highest-priority ready task on the lowest-index free worker whenever
 * both are available at the current instant.
 */

import { computePriority } from './graph.js'

function cmpName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

export function pack(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const names = [...tasks.keys()]

  const finish = new Map()
  const started = new Set()

  const workerBusyUntil = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])

  let t = 0
  let scheduledCount = 0
  const total = names.length

  while (scheduledCount < total) {
    let progressed = true
    while (progressed) {
      progressed = false

      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerBusyUntil[i] <= t) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      const ready = []
      for (const name of names) {
        if (started.has(name)) continue
        let allDone = true
        for (const dep of deps.get(name)) {
          if (!finish.has(dep) || finish.get(dep) > t) {
            allDone = false
            break
          }
        }
        if (allDone) ready.push(name)
      }
      if (ready.length === 0) break

      ready.sort((a, b) => {
        const pd = priority.get(b) - priority.get(a)
        if (pd !== 0) return pd
        return cmpName(a, b)
      })

      const task = ready[0]
      const workerIdx = freeWorkers[0]
      const start = t
      const fin = t + tasks.get(task)

      started.add(task)
      finish.set(task, fin)
      workerLog[workerIdx].push({ name: task, start, finish: fin })
      workerBusyUntil[workerIdx] = fin
      scheduledCount++
      progressed = true
    }

    if (scheduledCount === total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerBusyUntil[i] > t && workerBusyUntil[i] < next) next = workerBusyUntil[i]
    }
    t = next
  }

  let makespan = 0
  for (const f of finish.values()) if (f > makespan) makespan = f

  return { workerLog, makespan }
}
"}

