  const line = cur.line
  const col = cur.col
  let text = cur.advance()
  while (isIdentCont(cur.peek())) text += cur.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, line, col, text }
